npm install qrcode-terminal && node -e "const rl = require('readline').createInterface({ input: process.stdin, output: process.stdout }); process.stdin.resume(); const qr = require('qrcode-terminal'); rl.question('Digite a PRIMEIRA URL: ', u1 => { qr.generate(u1.trim(), { small: true }, q1 => { console.log(q1); rl.question('Digite a SEGUNDA URL: ', u2 => { qr.generate(u2.trim(), { small: true }, q2 => { console.log(q2); rl.close(); }); }); }); });"
